#include "palette_growth.h"
#include "document.h"
#include <iostream>
using namespace moon;
void check(bool v,const char* m){if(!v)throw std::runtime_error(m);}
int main(){try{
 const std::vector<int> base{4,9,12};auto p=paletteGrowthPreview(base,3,6);check(p.slots==std::vector<int>({4,9,12,-1,-2,-3})&&p.added==3&&p.handleSlot==6&&p.columns==3,"Legacy downward growth excludes handle");p=paletteGrowthPreview(base,0,0);check(p.slots==std::vector<int>{4}&&p.removedIds==std::vector<int>({9,12})&&p.handleSlot==1&&p.columns==1,"Minimum RGBA size one");p=paletteGrowthPreview(base,3,9000);check(p.added==4096&&p.handleSlot==4099,"Legacy growth limit");
 Document d(1,1);d.applyExtractedPalette({0x00010203,0x00010203,0xff000000});auto ids=d.palette().order();d.deletePaletteColors({ids[1]});const auto before=d.palette().slots;ids=d.palette().order();d.setPaletteRole(0x00010203,false,true);d.setPaletteRole(0xffabcdef,true,true);d.clearPaletteSelection();const auto primary=d.palette().primary,secondary=d.palette().secondary;const auto history=d.historySize();d.pastePaletteColors({0xff000000,0xff000000},{ids.size(),ids.size()+1},false,&ids);const auto grown=d.palette().order();check(grown.size()==ids.size()+2&&std::equal(ids.begin(),ids.end(),grown.begin())&&d.palette().selected.empty()&&d.palette().primary==primary&&d.palette().secondary==secondary&&d.historySize()==history+1,"Growth compact append, roles, no select, one transaction");check(d.paletteEntry(grown.back())->color==0xff000000&&grown[grown.size()-2]!=grown.back(),"Repeated black keeps unique IDs");d.undo();check(d.palette().slots==before&&d.palette().primary==primary&&d.palette().secondary==secondary,"Growth undo restores holes and roles");d.redo();check(d.palette().order()==grown,"Growth redo");const auto shrink=paletteGrowthPreview(grown,3,1);const auto h=d.historySize();d.deletePaletteColors(shrink.removedIds);check(d.palette().order()==std::vector<int>{grown.front()}&&d.historySize()==h+1&&d.palette().primary==primary&&d.palette().secondary==secondary,"Shrink one transaction, roles unchanged");d.undo();check(d.palette().order()==grown,"Shrink undo");d.redo();check(d.palette().order().size()==1,"Shrink redo");std::cout<<"Palette growth preview, compact append, IDs, roles and undo/redo passed\n";return 0;
}catch(const std::exception& e){std::cerr<<e.what()<<"\n";return 1;}}
